ehhez ird meg a .replit filet es a replit.nix et .replit file nak ezt kötelező tartalmaznia: [agent] expertMode = true 

 This flake.nix flake contains the following outputs:

   'futhark' (the default) is a derivation with a statically linked 'futhark'
    binary and manpages.

   'tarball' produces a release tarball; essentially just the 'futhark'
    derivation packaged up.

   'tarballnightly' produces a release tarball where the version number is "nightly".

 Just run

   nix build

 and look in 'result'.

 For the Haskell dependencies that diverge from our pinned Nixpkgs, we use
 cabal2nix like thus:

  $ cabal2nix cabal://sexpgrammar2.2.1 > nix/sexpgrammar.nix

 And then import them into the configuration.  Although note that Nixpkgs also
 tends to contain the newest version of each Hackage package, even if it is not
 the default.

 To update the Nixpkgs snapshot (which also includes tooling), use:

  $ nix flake update

 Also remember this guide: 
{
  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixosunstable";
  };

  outputs =
    { self, nixpkgs }:
    let
      lib = nixpkgs.lib;

      supportedSystems = [
        "x86_64linux"
        "aarch64linux"
        "x86_64darwin"
        "aarch64darwin"
      ];

      forAllSystems = lib.genAttrs supportedSystems;

      commit = self.rev or "unknown";

        Source filtering (shared) 
      cleanSource =
        src:
        builtins.path {
          name = "futharksrc";
          path = src;
          filter =
            path: type:
            let
              relPath = lib.removePrefix (toString src + "/") (toString path);
            in
            builtins.any (regex: builtins.match regex relPath != null) [
              "futhark.cabal"
              "Setup.hs"
              "LICENSE"
              "^src."
              "^rts."
              "^docs."
              "^prelude."
              "^assets."
              "^srctesting."
              "^tools."
            ];
        };
    in
    {
      packages = forAllSystems (
        system:
        let
          pkgs = import nixpkgs { inherit system; };
          python = pkgs.python313Packages;
          haskell = pkgs.haskell.packages.ghc910;

           The Nix 'system' convention is unfortunately the opposite of what we use
           in our tarballs, so flip them around here.
          platform =
            lib.replaceStrings
              [
                "x86_64linux"
                "aarch64linux"
                "x86_64darwin"
                "aarch64darwin"
              ]
              [
                "linuxx86_64"
                "linuxaarch64"
                "x86_darwin64"
                "darwinaarch64"
              ]
              system;

          pkgs' = import pkgs.path {
            inherit system;

            config.packageOverrides = pkgs: {
              haskellPackages = pkgs.haskellPackages.override {
                overrides = new: old: {
                   Custom dependencies for which Nixpkgs is too old.
                  lsp = new.callPackage ./nix/lsp.nix { };
                  lsptypes = new.callPackage ./nix/lsptypes.nix { };
                  lsptest = new.callPackage ./nix/lsptest.nix { };
                  futharkdata = new.callPackage ./nix/futharkdata.nix { };
                  futharkserver = new.callPackage ./nix/futharkserver.nix { };
                  futharkmanifest = new.callPackage ./nix/futharkmanifest.nix { };

                   This derivation builds a statically linked 'futhark'
                   executable on Linux; on other platforms it uses the default
                   sharedlibrary build.
                  futhark =
                    let
                      base = new.callCabal2nix "futhark" (cleanSource ./.) { };
                    in
                    pkgs.haskell.lib.overrideCabal base (old: {
                      enableLibraryProfiling = false;
                      isExecutable = true;
                      isLibrary = false;

                      enableSharedExecutables = !pkgs.stdenv.isLinux;
                      enableSharedLibraries = !pkgs.stdenv.isLinux;

                      configureFlags = [
                        "ghcoption=Werror"
                        "ghcoption=splitsections"
                      ]
                      ++ lib.optionals pkgs.stdenv.isLinux (
                        [
                           static linking
                          "ghcoption=optl=static"
                          "ghcoption=optl=lbz2"
                          "ghcoption=optl=lz"
                          "ghcoption=optl=lelf"
                          "ghcoption=optl=llzma"
                          "ghcoption=optl=lzstd"
                        ]
                        ++ map (p: "extralibdirs=${p}/lib") [
                          pkgs.glibc.static
                          (pkgs.ncurses.override { enableStatic = true; })
                          (pkgs.gmp6.override { withStatic = true; })
                          (pkgs.libffi.overrideAttrs { dontDisableStatic = true; })
                          (pkgs.numactl.overrideAttrs { dontDisableStatic = true; })
                          pkgs.zlib.static
                          (pkgs.xz.override { enableStatic = true; }).out
                          (pkgs.zstd.override { enableStatic = true; }).out
                          (pkgs.bzip2.override { enableStatic = true; }).out
                          (pkgs.elfutils.overrideAttrs { dontDisableStatic = true; }).out
                        ]
                      );

                      preBuild = "echo ${commit} > commitid";
                    });
                };
              };
            };
          };

           Compiled Futhark binary with documentation, parameterised over the
           version number in the file names.
          futhark =
            version:
            pkgs.stdenvNoCC.mkDerivation {
              pname = "futhark";
              version = version;
              src = cleanSource ./.;

              nativeBuildInputs = [
                pkgs'.haskellPackages.futhark
                python.sphinx
              ];

              buildPhase = ''
                make C docs man
              '';

              installPhase = ''
                mkdir p $out
                mkdir p $out/share/man/man1

                cp r tools/release/skeleton/ $out/
                cp r ${pkgs'.haskellPackages.futhark}/bin $out/bin
                cp r docs/_build/man/.1 $out/share/man/man1/
                cp LICENSE $out/
                echo "${commit}" > $out/commitid
              '';
            };

          tarball =
            futhark:
            pkgs.stdenvNoCC.mkDerivation {
              pname = "futharktarball";
              version = futhark.version;
              src = false;

              dontUnpack = true;

              nativeBuildInputs = [
                futhark
              ];

              buildPhase = ''
                mkdir p futhark${futhark.version}${platform}
                cp r ${futhark}/ futhark${futhark.version}${platform}/
                tar c f futhark${futhark.version}${platform}.tar.xz J mode 'u+w' futhark${futhark.version}${platform}
              '';

              installPhase = ''
                mkdir p $out
                cp futhark${futhark.version}${platform}.tar.xz $out/
              '';
            };

           Extract version number from Futhark derivation.
          versionFromCabal = pkgs'.haskellPackages.futhark.version;
        in
        {
          futhark = futhark versionFromCabal;

          tarball = tarball (futhark versionFromCabal);

          tarballnightly = tarball (futhark "nightly");

           default package
          default = futhark versionFromCabal;
        }
      );

      devShells = forAllSystems (
        system:
        let
          pkgs = import nixpkgs { inherit system; };
          python = pkgs.python313Packages;
          haskell = pkgs.haskell.packages.ghc910;
        in
        {
           A shell that only contains tools for style checking.
          style = pkgs.mkShell {
            nativeBuildInputs = (import ./nix/pkgsstyle.nix { inherit pkgs haskell python; });
          };

           A shell for running tests in CI.
          test = pkgs.mkShell {
            nativeBuildInputs = import ./nix/pkgstest.nix { inherit pkgs python; };
          };

           The main development shell that contains all development tools.
          default = pkgs.mkShell {
            nativeBuildInputs =
              (import ./nix/pkgsstyle.nix { inherit pkgs haskell python; })
              ++ (
                with pkgs;
                [
                  cabalinstall
                  cacert
                  curl
                  file
                  git
                  haskell.ghc
                  haskell.weeder
                  haskell.haskelllanguageserver
                  haskellPackages.graphmod
                        haskellPackages.applyrefact
                  xdot
                  pkgconfig
                  zlib
                  zlib.out
                  cabal2nix
                  nixfmt
                  ghcid
                  niv
                  ispc
                  python.python
                  python.mypy
                  python.black
                  python.cycler
                  python.numpy
                  python.pyopencl
                  python.matplotlib
                  python.jsonschema
                  python.sphinx
                  (python.sphinxcontribbibtex.overridePythonAttrs (_: {
                    doCheck = false;
                  }))
                  imagemagick  needed for literate tests
                ]
                ++ lib.optionals (stdenv.isLinux) [
                  openclheaders
                  oclicd
                  (callPackage ./nix/oclgrind.nix { })
                  rocmPackages.clr
                ]
              );
          };
        }
      );

      formatter = forAllSystems (system: nixpkgs.legacyPackages.${system}.nixfmttree);
    };
}

